mapper.select:
SELECT id, patent_number, patent_name, patent_type, applicant, applicant_enterprise_id, ipc_main, application_date, legal_status, maintenance_years, data_source, region_id, created_at, updated_at FROM patent WHERE applicant_enterprise_id = #{enterpriseId} AND is_deleted = 0
AND (patent_name LIKE CONCAT('%', #{keyword}, '%') OR patent_number LIKE CONCAT('%', #{keyword}, '%') OR applicant LIKE CONCAT('%', #{keyword}, '%'))
AND patent_type = #{patentType}
ORDER BY application_date DESC LIMIT #{offset}, #{limit}
